//! `SignalVariant` - the master enum of all output payload types.
//!
//! This is what gets broadcast. Each variant carries a typed payload.
//!
//! # Wire shape
//!
//! Adjacently tagged — `{ "type": "<kind>", "data": <payload> }` — so the
//! frontend receives a discriminated union it can `switch` on. The tag is the
//! lowercase kind name, the same string [`SignalKind`] serializes to.
//!
//! # Registry
//!
//! `SignalKind` (payload-free twin of this enum) is generated by strum; every
//! kind's routing, audience, rate and version live in its
//! [`SignalSpec`](super::spec::SignalSpec). Adding a variant here without a
//! spec does not compile.

use serde::{Deserialize, Serialize};
use specta::Type;
use strum::{EnumDiscriminants, EnumIter, IntoStaticStr};

use super::kinds::SinkKind;
use super::payloads::{
    AnalyticsPayload, BootStatus, ChatPayload, ContextPayload, GovernancePayload, InferencePayload,
    ModelsReadiness, SystemPayload,
};

/// The master enum of all signal output types.
#[derive(Clone, Debug, Serialize, Deserialize, Type, EnumDiscriminants)]
#[serde(tag = "type", content = "data", rename_all = "lowercase")]
#[strum_discriminants(
    name(SignalKind),
    derive(Hash, EnumIter, IntoStaticStr, Serialize, Deserialize, Type),
    strum(serialize_all = "lowercase"),
    serde(rename_all = "lowercase"),
    doc = "Payload-free kind of a signal — the registry key (see `SignalSpec`)."
)]
pub enum SignalVariant {
    /// Chat message (LLM response, user message)
    Chat(ChatPayload),
    /// Analytics event
    Analytics(AnalyticsPayload),
    /// Retrieved context (RAG)
    Context(ContextPayload),
    /// Inference metrics
    Inference(InferencePayload),
    /// System status change
    System(SystemPayload),
    /// Governance event (lane routing, rate limits, council)
    Governance(GovernancePayload),
    /// Hardware snapshot (CPU / RAM / GPU / VRAM).
    Hardware(crate::platform::HardwareMetrics),
    /// Models readiness (decides whether setup opens).
    Models(ModelsReadiness),
    /// Platform boot progress (phase + per-step status).
    Boot(BootStatus),
    /// The bridge fell behind: windows re-read the state snapshot.
    Resync,
}

impl SignalVariant {
    /// The registry key of this variant.
    #[must_use]
    pub fn kind(&self) -> SignalKind {
        SignalKind::from(self)
    }

    /// Routing destinations, from the registry.
    #[must_use]
    pub fn sinks(&self) -> &'static [SinkKind] {
        self.kind().spec().sinks
    }

    /// Wire name of this variant (`"hardware"`, `"system"`, …).
    #[must_use]
    pub fn name(&self) -> &'static str {
        self.kind().into()
    }
}
